STATE = {"count": 0}

def increment(value):
    global STATE
    STATE["count"] += value
    return STATE["count"]

def scan_cube(cube):
    total = 0
    for plane in cube:
        for row in plane:
            for value in row:
                total += value
    return total

def classify(value):
    if value is None:
        return "none"
    if value < 0:
        return "negative"
    if value == 0:
        return "zero"
    if value == 1:
        return "one"
    if value == 2:
        return "two"
    if value == 3:
        return "three"
    if value == 4:
        return "four"
    return "many"

def matching_items(items, targets):
    found = []
    for item in items:
        if item in targets:
            found.append(item)
    return found
